DROP ALL OBJECTS;
CREATE TABLE cafe_student (id BIGINT AUTO_INCREMENT PRIMARY KEY,student_no VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(80),dingtalk_user_id VARCHAR(100) UNIQUE,password_hash VARCHAR(100),first_login_time TIMESTAMP,last_login_time TIMESTAMP,creator VARCHAR(64) DEFAULT '',create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updater VARCHAR(64) DEFAULT '',update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted BOOLEAN DEFAULT FALSE);
CREATE TABLE cafe_order (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(40) NOT NULL UNIQUE,student_id BIGINT,student_no VARCHAR(40),student_name VARCHAR(80),status INT,business_date DATE,pos_order_no VARCHAR(20),total_price INT,cup_count INT,entered_time TIMESTAMP,done_time TIMESTAMP,failure_reason VARCHAR(200),request_key VARCHAR(64),fingerprint VARCHAR(64),version INT DEFAULT 0,retry_after TIMESTAMP,creator VARCHAR(64) DEFAULT '',create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updater VARCHAR(64) DEFAULT '',update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted BOOLEAN DEFAULT FALSE,UNIQUE(business_date,pos_order_no),UNIQUE(student_id,request_key));
CREATE TABLE cafe_order_item(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT,item_id BIGINT,name VARCHAR(100),name_en VARCHAR(100),image_url VARCHAR(1000),unit_price INT,quantity INT,options_text VARCHAR(1000),options VARCHAR(4000),creator VARCHAR(64) DEFAULT '',create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updater VARCHAR(64) DEFAULT '',update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted BOOLEAN DEFAULT FALSE);
INSERT INTO cafe_student(id,student_no,name,first_login_time,last_login_time) VALUES(1,'S001','测试学生',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),(2,'S002','另一位学生',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
